--
-- Name: nocs; Type: TABLE; Schema: public; Owner: workbc
--

CREATE TABLE public.nocs (
    noc_2021 text NOT NULL,
    label_en text,
    definition_en text,
    label_fr text,
    definition_fr text,
    noc_level integer,
    teer_level integer,
    parent_noc text,
    noc_2016 text
);


ALTER TABLE public.nocs OWNER TO workbc;

--
-- Name: TABLE nocs; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON TABLE public.nocs IS 'NOC 2021 Hierarchy';


--
-- Name: COLUMN nocs.noc_2021; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.noc_2021 IS 'NOC 2021';


--
-- Name: COLUMN nocs.label_en; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.label_en IS 'English label';


--
-- Name: COLUMN nocs.definition_en; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.definition_en IS 'English definition';


--
-- Name: COLUMN nocs.label_fr; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.label_fr IS 'French label';


--
-- Name: COLUMN nocs.definition_fr; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.definition_fr IS 'French definition';


--
-- Name: COLUMN nocs.noc_level; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.noc_level IS 'NOC level: 1 (Broad category), 2 (Major group), 3 (Sub-major group), 4, (Minor group), 5 (Unit group)';


--
-- Name: COLUMN nocs.teer_level; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.teer_level IS 'TEER level (0-5)';


--
-- Name: COLUMN nocs.parent_noc; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.parent_noc IS 'Parent NOC';


--
-- Name: COLUMN nocs.noc_2016; Type: COMMENT; Schema: public; Owner: workbc
--

COMMENT ON COLUMN public.nocs.noc_2016 IS 'Equivalent NOC 2016 codes (comma-separated)';


--
-- Name: nocs_categories; Type: VIEW; Schema: public; Owner: workbc
--

CREATE VIEW public.nocs_categories AS
 SELECT nocs.noc_2021,
    nocs.label_en AS label,
    nocs.noc_level AS level
   FROM public.nocs
  WHERE (nocs.noc_level < 5);


ALTER TABLE public.nocs_categories OWNER TO workbc;

--
-- Name: nocs_nocs; Type: VIEW; Schema: public; Owner: workbc
--

CREATE VIEW public.nocs_nocs AS
 SELECT nocs.noc_2021,
    nocs.label_en AS label,
    nocs.label_fr,
    nocs.noc_2016
   FROM public.nocs
  WHERE (nocs.noc_level = 5);


ALTER TABLE public.nocs_nocs OWNER TO workbc;

